INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63519972', 63519972, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'BALAI BESAR PENGEMBANGAN SDM DAN PENELITIAN KOMUNIKASI DAN INFORMATIKA MEDAN', 'Belanja Barang Persediaan Barang Konsumsi', 'Barang', 'E-Purchasing', 'Sumatera Utara, Medan (Kota)', 153253000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Pengadaan Alat Tulis Kantor (ATK) dan komputer supplies untuk mendukung operasional perkantoran, meliputi antara lain kertas, pena, pensil, map, tinta printer, toner, stapler, dan perlengkapan administrasi lainnya. 2. Pengadaan payung custom dengan desain khusus sesuai identitas instansi, termasuk proses desain, pencetakan logo/identitas, serta distribusi barang dalam kondisi siap pakai. 3. Pengadaan buku laporan tahunan, meliputi penyusunan desain layout, pencetakan, penjilidan, serta pengemasan dokumen laporan dalam bentuk buku cetak dengan kualitas sesuai standar percetakan.', 'Spesifikasi Pekerjaan 1. ATK dan Komputer Supplies Pengadaan perlengkapan administrasi dan kebutuhan operasional perkantoran berupa kertas, alat tulis, perlengkapan arsip, serta tinta/toner printer atau perlengkapan komputer pendukung lainnya. Barang harus baru, berkualitas baik, dan layak pakai. 2. Payung Custom Beridentitas Instansi Pengadaan payung dengan bahan tahan air dan rangka kuat, dilengkapi cetak logo atau identitas instansi yang rapi dan tidak mudah luntur. Barang dalam kondisi baru dan siap digunakan. 3. Buku Laporan Tahunan Pengadaan buku laporan tahunan dalam bentuk cetak, meliputi desain tata letak, pencetakan, dan penjilidan dengan kualitas baik, rapi, dan siap didistribusikan. Ketentuan Umum: Seluruh barang harus baru, sesuai spesifikasi, dikemas dengan baik, dan diantar ke lokasi yang ditentukan oleh satuan kerja.', 20000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 997273);
