INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63518916', 63518916, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS LINGKUNGAN HIDUP', 'Belanja Pemeliharaan Alat Laboratorium-Alat Laboratorium Lingkungan Hidup- Laboratorium Lingkungan (Pemeliharaan Alat Pantau Udara (AQMS)', 'Jasa Lainnya', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 374625000, 'April 2026', 'APBD', 1, 1, '1 Paket', 'Pemeliharaan sarana pemantauan udara ambien mencakup kalibrasi dan perawatan meliputi pembongkaran dan pemasangan serta instalasi alat pemantau udara. Pemeliharaan dilakukan dengan melibatkan pihak ketiga yang kompeten dalam pemeliharaan alat pemantau udara otomatis.', 'Merupakan perusahaan penyedia jasa pemeliharaan yang memahami dan berpengalaman dalam memelihara alat pemantauan udara merk Aeroqual dengan metodologi :1. Dilakukan mengikuti manual book alat dan prosedur lain sesuai dengan spesifikasi alat yang akan dipelihara. Metode service mencakup pengecekan dan indentifikasi kerusakan, pengujian sistem operasi, dan pengujian masa operasi;2. Kalibrasi alat dilakukan dengan mengikuti manual book alat. Parameter ozon (O3), Natrium Dioksida (NO2), Sulfhur Dioksida (SO2), Karbon Monoksida (CO), Hidrokarbon (HC), PM2,5 dan PM10 membutuhkan kalibrasi menggunakan gas standar. Penggunaan standar-standar lain berdasarkan ketentuan perusahaan pembuat alat dapat dilakukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 998993);
